%% Figure 6 - 35-dimensional infinite-horizon optimal control problem (Section 6.5)
%
% Stationary HJB with known solution, d = 35, beta = 1, q = I and drift
% f_i(x) = -kappa_i x_i on [-1, 1]^35.
% The data (20000 training and 5000 validation samples) are generated by generate_hjb35d_data.m.
% Hyperbolic cross dictionary J = 3 (P = 10396), Lasso lambda = 1e-8.
% In (a)-(d), Algorithm 2 starts from 10 random samples and the constant
% basis function and runs 50 iterations, e_SL (26) uses omega_1 = 1,
% omega_2 = 1/d, and the data score (28) uses omega_1 = omega_2 = 1.
%   (a) 35d_SL_greedy.png    e_SL (26)        + data selection, score (28)
%   (b) 35d_SL_random.png    e_SL (26)        + random data
%   (c) 35d_PDE_greedy.png   e~_PDE (27)      + data selection, score (28)
%   (d) 35d_PDE_random.png   e~_PDE (27)      + random data
%   (e) 35d_full.png         full basis (all P) + random data
% All panels use the same seeds: run r starts from the same 10 samples in
% every panel, and the random-data panels add the same random samples.
% Means over 100 runs.

clear; close all;
root = fileparts(mfilename('fullpath'));
addpath(genpath(fullfile(root, 'functions')));

n_runs = 100;
seed = 2026;

panels = { % panel  basis    data      file
           'a',     'SL',    'score',  '35d_SL_greedy';
           'b',     'SL',    'random', '35d_SL_random';
           'c',     'PDE',   'score',  '35d_PDE_greedy';
           'd',     'PDE',   'random', '35d_PDE_random';
           'e',     'fixed', 'random', '35d_full'};

D = generate_hjb35d_data();
d = D.d;
NN = hyperbolic_cross_set(d, 3);
P = size(NN, 1);

res = cell(size(panels, 1), 1);
for k = 1:size(panels, 1)
    fprintf('Figure 6(%s): %s basis, %s data\n', panels{k, 1:3});
    opt = struct('basis_rule', panels{k, 2}, 'data_rule', panels{k, 3}, ...
                 'n_iter', 50, 'n_init_data', 10, 'n_init_basis', 1, ...
                 'lambda', 1e-8, 'omega_basis', [1, 1/d], 'omega_data', [1, 1], ...
                 'n_runs', n_runs, 'seed', seed);
    if strcmp(panels{k, 2}, 'fixed')
        opt.n_init_basis = P;               % full dictionary
    end
    res{k} = data_driven_greedy(D, NN, opt);
end

for k = 1:size(panels, 1)
    if strcmp(panels{k, 2}, 'fixed')
        fig = plot_hjb35d(res{k}, 'full');
    else
        fig = plot_hjb35d(res{k}, 'adaptive');
    end
    save_figure(fig, fullfile(root, 'figures', [panels{k, 4} '.png']));
end
 